fn run_module_tests(module_names: &[&str]) {
    let all = cases();
    let module_cases: Vec<_> = all
        .into_iter()
        .filter(|c| module_names.contains(&c["module"].as_str().unwrap_or_default()))
        .collect();
    assert!(
        !module_cases.is_empty(),
        "no cases for modules: {:?}",
        module_names
    );

    let mut failed: Vec<String> = Vec::new();
    let mut checked = 0usize;

    for case in &module_cases {
        let id = case["id"].as_str().unwrap_or_default();
        let expected = &case["output"];
        let actual = run_case(case);
        checked += 1;

        match (expects_failure(expected), actual) {
            (false, Ok(value)) => {
                if &value != expected {
                    failed.push(format!("{id}: expected {expected}, got {value}"));
                }
            }
            (false, Err(e)) => {
                failed.push(format!("{id}: expected {expected}, got the error {e}"));
            }
            (true, Ok(value)) => {
                failed.push(format!("{id}: expected a failure, got {value}"));
            }
            (true, Err(_)) => {}
        }
    }

    if !failed.is_empty() {
        for line in &failed {
            eprintln!("[FAIL] {line}");
        }
        panic!(
            "{} of {} studio logic golden cases differ on the Rust side (modules: {:?})",
            failed.len(),
            checked,
            module_names
        );
    }

    eprintln!(
        "studio_logic_golden: {checked} cases replayed, all match (modules: {:?})",
        module_names
    );
}

